# FinderX Termux launcher. First prerequisite: `pkg install -y python curl`
# The program payload is compressed and encoded to discourage casual reading; it is not encrypted.
import os as _os, sys as _sys, subprocess as _sub, shutil as _shutil
import base64 as _b64, zlib as _zlib
from pathlib import Path as _Path

def _is_termux():
    return bool(_os.environ.get("TERMUX_VERSION") or _os.environ.get("PREFIX", "").startswith("/data/data/") or _Path("/data/data/com.termux/files/usr/bin/pkg").exists())

def _prepare_termux():
    if not _is_termux():
        return
    if _sys.version_info < (3, 8):
        raise SystemExit("FinderX needs Python 3.8+. Update Termux, then run: pkg install python")
    _app = _Path.home() / "FinderX"
    _app.mkdir(parents=True, exist_ok=True)
    _target = _app / "FinderX.py"
    _here = _Path(__file__).resolve()
    if _here != _target.resolve():
        _shutil.copy2(_here, _target)
        _os.execv(_sys.executable, [_sys.executable, str(_target), *_sys.argv[1:]])
    _venv = _app / ".venv"
    _py = _venv / "bin" / "python"
    if not _py.exists():
        try:
            _sub.check_call([_sys.executable, "-m", "venv", str(_venv)])
        except Exception as _exc:
            raise SystemExit("Could not create Python environment. Run `pkg install python` in Termux and retry.\n" + str(_exc))
    _check = _sub.run([str(_py), "-c", "import requests, urllib3, openpyxl"], stdout=_sub.DEVNULL, stderr=_sub.DEVNULL)
    if _check.returncode:
        print("First-time setup: installing FinderX Python packages...", flush=True)
        _packages = ["requests>=2.28,<3", "urllib3>=1.26,<3", "openpyxl>=3.0,<4"]
        try:
            _sub.check_call([str(_py), "-m", "pip", "install", "--disable-pip-version-check", *_packages])
        except Exception as _exc:
            raise SystemExit("Package install failed. Check internet and Termux Python; retry `pkg install python`.\n" + str(_exc))
    if _Path(_sys.prefix).resolve() != _venv.resolve():
        _os.execv(str(_py), [str(_py), str(_target), *_sys.argv[1:]])

_prepare_termux()
